-- Health Education final module. Run seed_health_course.sql first. Safe to run more than once.

do $seed$
declare cid uuid;
begin
  select id into cid from public.courses where slug = 'health-education';
  if cid is null then raise exception 'Run the course file first'; end if;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 4, $j$Final Assessment: My Personal Wellness Plan$j$, $j${"prompt": "Create a Personal Wellness Plan of at least 500 words and prepare a short presentation of its main ideas. Use complete sentences and label each part. Do not include private medical details, diagnoses, addresses, phone numbers or passwords, and review your plan with a parent or guardian before you submit it. 1 Corinthians 6:19 and 20 says, What? know ye not that your body is the temple of the Holy Ghost which is in you, which ye have of God, and ye are not your own? For ye are bought with a price: therefore glorify God in your body, and in your spirit, which are God's.\n\nPart 1: Wellness goals. Write one SMART goal for each of the four parts of health: physical, mental and emotional, social and spiritual.\nPart 2: Daily habits. Plan a day of meals using the five food groups, sixty minutes of activity, a sleep schedule of eight to ten hours and a hygiene routine.\nPart 3: Stress and mental health. Name three healthy coping skills and explain what to do and who to contact if you or a friend is in crisis, including 988 and 911.\nPart 4: Risk and prevention. Write a refusal plan for alcohol, nicotine and drugs, a home safety and emergency plan with the steps of Hands only CPR, and four ways to prevent infection.\nPart 5: Relationships. Describe your personal standards, your boundaries and how you will treat others with respect, including online safety rules.\nPart 6: Health information. Explain how you will check a health claim and where you would go for a checkup, an urgent problem and an emergency.\nPart 7: Service and advocacy. Plan one act of health advocacy or service for your family, church or community.\nPart 8: Faith and reflection. Apply at least two Scriptures from the King James Version to your plan and explain what you learned and your next step.\nPart 9: Presentation plan. List five main points you would share in a three minute talk.", "rubric": "100 points. Part 1: 10 points. Part 2: 15 points. Part 3: 15 points. Part 4: 15 points. Part 5: 10 points. Part 6: 10 points. Part 7: 5 points. Part 8: 8 points. Part 9: 4 points. Grammar, conventions and respectful tone: 8 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Final Assessment: My Personal Wellness Plan$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 16, $j$Final Exam: Health Education$j$, $j${"questions": [{"q": "The four parts of health are physical, mental and emotional, social and:", "options": ["Spiritual", "Political", "Seasonal", "Financial"]}, {"q": "Half of your plate should be:", "options": ["Fried foods", "Soda", "Fruits and vegetables", "Desserts"]}, {"q": "Teens need at least how much activity each day?", "options": ["Five minutes", "None", "One hour per month", "Sixty minutes"]}, {"q": "Teens need about how much sleep each night?", "options": ["Three hours", "Eight to ten hours", "Five hours", "Fourteen hours"]}, {"q": "To call or text the Suicide and Crisis Lifeline, dial:", "options": ["988", "511", "211", "311"]}, {"q": "The legal age to buy tobacco and nicotine products is:", "options": ["Sixteen", "Twenty one", "Fifteen", "Eighteen"]}, {"q": "Pills bought online or from friends may contain:", "options": ["Fentanyl", "Only sugar", "Nothing", "Only vitamins"]}, {"q": "Antibiotics treat:", "options": ["The flu", "Any virus", "Bacterial infections", "Colds"]}, {"q": "Hands only CPR is performed at about how many compressions per minute?", "options": ["30", "60", "200", "100 to 120"]}, {"q": "An upstander is someone who:", "options": ["Reposts it", "Ignores it", "Stands with the person and reports bullying", "Joins the bully"]}, {"q": "Which is a warning sign of dating violence?", "options": ["Respect", "Honesty", "Controlling behavior and threats", "Kindness"]}, {"q": "In the DECIDE model, the first step is to:", "options": ["Decide", "Define the problem", "Guess", "Evaluate"]}, {"q": "Abstinence until marriage is:", "options": ["Unknown", "The only certain way to avoid pregnancy and sexually transmitted infections", "Required by no one", "Harmful"]}, {"q": "A reliable source of health information is:", "options": ["A miracle cure ad", "The CDC or a doctor", "A rumor", "An unnamed post"]}, {"q": "1 Corinthians 6:19 calls the body:", "options": ["Unimportant", "The temple of the Holy Ghost", "A machine only", "A tool for money"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: Health Education$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,3,1,0,1,0,2,3,2,2,1,1,1,1}'::int[], array[$j$Whole person health includes spiritual health.$j$,$j$MyPlate suggests half fruits and vegetables.$j$,$j$Daily activity supports health.$j$,$j$Sleep supports learning, mood and growth.$j$,$j$988 connects to trained counselors.$j$,$j$The age is twenty one.$j$,$j$Counterfeit pills can be deadly.$j$,$j$Antibiotics do not work on viruses.$j$,$j$Push hard and fast at that rate.$j$,$j$Upstanders take safe action.$j$,$j$Control is not love.$j$,$j$You begin by defining the problem.$j$,$j$It is the expected standard and fully protective.$j$,$j$Credible sources use evidence.$j$,$j$Scripture calls us to honor the body.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: Health Education$j$ on conflict (item_id) do nothing;
end
$seed$;
